import {referenceAudioTask} from './breakdown.js';
import {textSampleTimes,extractTextLines,buildTextTracks,textSteps,textEvidenceReport} from './text-evidence-core.js';
const $=id=>document.getElementById(id);let worker=null,controller=null,latest=null;
function waitEvent(video,name,signal){return new Promise((resolve,reject)=>{const cleanup=()=>{clearTimeout(timer);video.removeEventListener(name,done);video.removeEventListener('error',fail);signal.removeEventListener('abort',abort)},done=()=>{cleanup();resolve()},fail=()=>{cleanup();reject(Error('视频画面无法解码'))},abort=()=>{cleanup();reject(Error('文字识别已停止'))},timer=setTimeout(()=>{cleanup();reject(Error('读取视频画面超时'))},15000);video.addEventListener(name,done,{once:true});video.addEventListener('error',fail,{once:true});signal.addEventListener('abort',abort,{once:true});if(signal.aborted)abort()})}
function abortable(promise,signal){return new Promise((resolve,reject)=>{const clean=()=>{clearTimeout(timer);signal.removeEventListener('abort',abort)},abort=()=>{clean();reject(Error('文字识别已停止'))},timer=setTimeout(()=>{clean();reject(Error('文字识别等待超时，请检查网络或缩短视频'))},120000);signal.addEventListener('abort',abort,{once:true});Promise.resolve(promise).then(v=>{clean();resolve(v)},e=>{clean();reject(e)});if(signal.aborted)abort()})}

async function engine(signal){const {default:{createWorker}}=await abortable(import('https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.esm.min.js'),signal);if(signal.aborted)throw Error('文字识别已停止');const creating=createWorker('chi_sim',1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.0.0',logger:m=>{if(signal.aborted)return;$('text-status').textContent=`正在识别画面文字：${m.status} ${Number.isFinite(m.progress)?Math.round(m.progress*100)+'%':''}`}}).then(result=>{if(signal.aborted){result.terminate();throw Error('文字识别已停止')}return result});const result=await abortable(creating,signal);await result.setParameters({tessedit_pageseg_mode:'6'});return result}
async function recognizeFrame(canvas,time,signal){
 const w=canvas.width,h=canvas.height,lines=[],raw=[],crop=document.createElement('canvas');crop.width=w;crop.height=Math.ceil(h/2);const ctx=crop.getContext('2d');
 for(const top of [0,Math.floor(h/4),Math.floor(h/2)]){if(signal.aborted)throw Error('文字识别已停止');ctx.drawImage(canvas,0,top,w,Math.min(crop.height,h-top),0,0,w,crop.height);const {data}=await abortable(worker.recognize(crop,{}, {blocks:true}),signal);raw.push(data.text||'');for(const line of extractTextLines(data,w,crop.height,time)){line.box.y=(top+line.box.y*crop.height)/h;line.box.h=line.box.h*crop.height/h;const norm=t=>t.replace(/[\s\p{P}\p{S}]/gu,'').toLowerCase();if(!lines.some(x=>norm(x.text)===norm(line.text)&&Math.abs(x.box.y-line.box.y)<.1))lines.push(line)}}
 return{time,rawText:raw.join('\n---\n'),image:canvas.toDataURL('image/jpeg',.75),lines};
}

function display(data,selftest){const box=$('text-results');box.replaceChildren();const p=document.createElement('p');p.textContent=`${selftest?'模型自检示意图 · ':''}${data.frames.length} 帧，间隔约 ${data.step.toFixed(2)} 秒；${data.tracks.length} 条文字候选。不会自动写入字幕。`;box.append(p);for(const t of data.tracks){const card=document.createElement('details'),summary=document.createElement('summary');summary.textContent=`${t.start.toFixed(2)}–${t.end.toFixed(2)} 秒 · ${t.text}${t.moving?' · 位置变化':''}${t.scaling?' · 尺寸变化':''}`;card.append(summary);if(!selftest){const seek=document.createElement('button');seek.className='secondary';seek.textContent='播放此处核对';seek.onclick=()=>document.dispatchEvent(new CustomEvent('reference-seek',{detail:t.start}));card.append(seek)}const list=document.createElement('ol');textSteps(t).forEach(text=>{const li=document.createElement('li');li.textContent=text;list.append(li)});card.append(list);box.append(card)}if(!selftest){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='核对实际 OCR 采样画面与原始文字（可能含误识别）';details.append(summary);const grid=document.createElement('div');grid.className='text-sample-grid';for(const f of data.frames){const figure=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption');img.src=f.image;img.alt=`${f.time.toFixed(2)} 秒实际 OCR 输入`;img.loading='lazy';caption.textContent=`${f.time.toFixed(2)} 秒 · 原始识别：${f.rawText||'没有文字'}`;figure.append(img,caption);grid.append(figure)}details.append(grid);box.append(details)}if(!data.tracks.length){const p=document.createElement('p');p.textContent='未获得可靠文字，不能认定没有字幕。';box.append(p)}}
async function run(selftest=false){controller=new AbortController();const signal=controller.signal;latest=null;try{$('text-stop').hidden=false;$('text-download').disabled=true;$('text-status').textContent='正在加载开源文字识别引擎，首次需要下载中英文语言包…';const data=await referenceAudioTask(async({file,reference})=>{worker=await engine(signal);const frames=[];let step=1;if(selftest){const canvas=$('text-test-canvas'),ctx=canvas.getContext('2d');canvas.hidden=false;ctx.fillStyle='#fff';ctx.fillRect(0,0,960,540);ctx.fillStyle='#111';ctx.font='bold 60px sans-serif';ctx.fillText('CUT TO THE BEAT',80,220);ctx.font='bold 60px sans-serif';ctx.fillText('剪辑节奏',80,340);frames.push(await recognizeFrame(canvas,0,signal));}else{const url=URL.createObjectURL(file),video=document.createElement('video');video.muted=true;video.preload='auto';video.playsInline=true;const canvas=document.createElement('canvas');canvas.width=Math.min(960,reference.width);canvas.height=Math.round(canvas.width*reference.height/reference.width);if(canvas.height>960){canvas.height=960;canvas.width=Math.round(960*reference.width/reference.height)}const ctx=canvas.getContext('2d',{willReadFrequently:true});try{const ready=waitEvent(video,'loadeddata',signal);video.src=url;video.load();await ready;const times=textSampleTimes(reference.duration);step=reference.duration/times.length;for(let i=0;i<times.length;i++){if(signal.aborted)throw Error('文字识别已停止');const ready=waitEvent(video,'seeked',signal);video.currentTime=times[i];await ready;ctx.drawImage(video,0,0,canvas.width,canvas.height);$('text-status').textContent=`识别画面文字 ${i+1}/${times.length} · ${times[i].toFixed(2)} 秒`;frames.push(await recognizeFrame(canvas,times[i],signal))}}finally{video.pause();video.removeAttribute('src');video.load();URL.revokeObjectURL(url)}}if(signal.aborted)throw Error('文字识别已停止');return{frames,step,tracks:buildTextTracks(frames,step),source:selftest?'selftest':reference.name}},{example:selftest,stopId:'text-stop',taskName:'识别画面文字'});latest=data;display(data,selftest);$('text-download').disabled=false;if(!selftest)document.dispatchEvent(new CustomEvent('text-evidence-result',{detail:data}));$('text-status').textContent=selftest&&!data.tracks.some(t=>t.text.replace(/\s/g,'').includes('剪辑节奏'))?'自检部分通过：识别到英文；中文测试未通过，暂不能依赖中文识别。':`文字识别完成：${data.tracks.length} 条候选。展开文字查看位置、尺寸线索与剪映步骤；未识别的花字、动画和字体仍需核对。`}catch(e){controller?.abort();$('text-status').textContent='文字识别未完成：'+e.message}finally{await worker?.terminate().catch(()=>{});worker=null;controller=null;$('text-stop').hidden=true}}
$('text-start').onclick=()=>run();$('text-selftest').onclick=()=>run(true);$('text-stop').onclick=()=>{controller?.abort();worker?.terminate();worker=null;$('text-status').textContent='正在停止文字识别…'};
$('text-download').onclick=()=>{if(!latest)return;const url=URL.createObjectURL(new Blob([JSON.stringify(latest,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ClipPilot-画面文字证据.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};
document.addEventListener('reference-changed',()=>{latest=null;$('text-results').replaceChildren();$('text-test-canvas').hidden=true;$('text-download').disabled=true;$('text-status').textContent='视频已更换，尚未识别画面文字。'});
export {textEvidenceReport};
